import {renderHorizonArchitecture} from './horizon-architecture.js';
import {nativeMedia} from './engine-media.js';
// Product-facing narrative; provenance and measurement scope live in CONTENT.md.
const text={
 en:{
  horizonTag:'01 / IGNIS HORIZON · GEOMETRY + VISIBILITY',horizonTitle:'Give your world<br><em>a bigger horizon.</em>',horizonBody:'Forested valleys. Mountain ranges. Thousands of objects sharing one landscape. Horizon brings together Ignis’s native geometry, visibility and distant-representation technologies so the renderer spends its work where it shapes the image.',
  horizonLink:'Explore Horizon',trees:'trees in the dense-forest scene',meshes:'mesh instances in that scene',distance:'to the far mountain-chain center in the landscape study',method:'Inside the technology',methodBody:'Content-shared geometry, resident GPU resources, conservative visibility, two-scale GPU occlusion and atmosphere-aware compiled representations work together. Adaptive occluders reduced draw + GPU-wait time from 92.530 to 48.724 ms (1.90×) in the first-person 1728×1117 test on Apple M4 Pro/Metal. These are controlled render measurements, not gameplay FPS. The forest and 18 km landscape are separate scenes. Regional geometric LOD/IGL remains an experimental branch, off by default.',
  plantsTag:'02 / PROCEDURAL PLANT GENERATION',plantsTitle:'From a blade of grass.<br><em>To an ancient tree.</em>',plantsBody:'Build vegetation from its living architecture: stems, trunks, branches, leaves, roots and buttresses. Ignis generates the geometry from editable rules and seeds. Change the structure, choose an age, shape the crown and create a family of plants with a shared identity.',
  plantsList:['Generate plants from constructive organs and curves.','Author branching, leaf shapes, root systems and growth profiles.','Regenerate, prune and sculpt through the editor or MCP.'],plantsLink:'Explore plant generation',plantsNote:'An extensible construction system, with native grass/groundcover and palm, plane, eucalyptus and fig-tree exemplars. Authored age profiles accept 0.25–2,000 years; species fidelity depends on the recipe and artistic work. Age is an authoring parameter, not a simulation of biological millennia.',
  worldTag:'03 / LANDSCAPES WITH DEPTH',worldTitle:'Build the distance.<br><em>Shape the atmosphere.</em>',worldBody:'Author ridges, slopes and mountain silhouettes. Compose atmospheric layers and palettes. Keep terrain geometry available for physical exploration while visual representations respond to the view.',worldLink:'Explore worlds and terrain',
  promisesTag:'ONE ENGINE. CONNECTED POSSIBILITIES.',promises:[['Characters with an inner world.','Give NPCs perception, memory, personality, routines and coordinated tactics. Inspect what they know and why they act.','npcs'],['Create together with AI.','Humans and agents use the same engine contracts. Generate, edit, run, inspect and undo through MCP and the native editor.','tools'],['Your world can run offline.','Single player is local. Authoritative multiplayer is optional. Keep creation, simulation and durable saves under your control.','network']],read:'Explore system',
  galleryTag:'NATIVE CAPTURES / SELECTED VIEWS',galleryTitle:'See it<br><em>take shape.</em>',galleryBody:'A closer look at the landscapes, vegetation and architecture created with Ignis. Select a view or open it at full size.'
 },
 pt:{
  horizonTag:'01 / IGNIS HORIZON · GEOMETRIA + VISIBILIDADE',horizonTitle:'Dê ao seu mundo<br><em>um horizonte maior.</em>',horizonBody:'Vales cobertos de floresta. Cadeias de montanhas. Milhares de objetos compartilhando uma paisagem. Horizon reúne as tecnologias nativas de geometria, visibilidade e representação distante da Ignis para concentrar o trabalho do renderizador onde ele forma a imagem.',
  horizonLink:'Explore o Horizon',trees:'árvores na cena de floresta densa',meshes:'instâncias de malha nessa cena',distance:'até o centro da cadeia mais distante no estudo de paisagem',method:'Por dentro da tecnologia',methodBody:'Geometria compartilhada por conteúdo, recursos residentes na GPU, visibilidade conservadora, oclusão GPU em duas escalas e representações compiladas sensíveis à atmosfera trabalham juntas. Oclusores adaptativos reduziram draw + espera GPU de 92,530 para 48,724 ms (1,90×) no ensaio em primeira pessoa 1728×1117, Apple M4 Pro/Metal. São medições controladas de renderização, não FPS de gameplay. A floresta e a paisagem a 18 km são cenas distintas. LOD geométrico regional/IGL segue experimental, desligado por padrão.',
  plantsTag:'02 / GERAÇÃO PROCEDURAL DE PLANTAS',plantsTitle:'Da folha de grama.<br><em>À árvore milenar.</em>',plantsBody:'Construa vegetação a partir da sua arquitetura: hastes, troncos, galhos, folhas, raízes e contrafortes. A Ignis gera a geometria a partir de regras editáveis e sementes. Mude a estrutura, escolha uma idade, desenhe a copa e crie famílias de plantas com identidade própria.',
  plantsList:['Gere plantas por órgãos construtivos e curvas.','Defina ramificação, formas de folhas, raízes e perfis de crescimento.','Regenere, pode e esculpa pelo editor ou pelo MCP.'],plantsLink:'Explore a geração de plantas',plantsNote:'Sistema construtivo extensível, com gramas/coberturas nativas e exemplares de palmeira, plátano, eucalipto e figueiras. Perfis de idade autorais aceitam 0,25–2.000 anos; fidelidade de espécie depende da receita e do trabalho artístico. Idade é um parâmetro de autoria, não uma simulação de milênios biológicos.',
  worldTag:'03 / PAISAGENS COM PROFUNDIDADE',worldTitle:'Construa a distância.<br><em>Desenhe a atmosfera.</em>',worldBody:'Modele cristas, encostas e silhuetas de montanhas. Componha camadas atmosféricas e paletas. Conserve a geometria do terreno para exploração física enquanto as representações visuais respondem à vista.',worldLink:'Explore mundos e terrenos',
  promisesTag:'UMA ENGINE. POSSIBILIDADES CONECTADAS.',promises:[['Personagens com um mundo interior.','Dê aos NPCs percepção, memória, personalidade, rotinas e táticas coordenadas. Inspecione o que sabem e por que agem.','npcs'],['Crie junto com a IA.','Humanos e agentes usam os mesmos contratos da engine. Gere, edite, execute, inspecione e desfaça pelo MCP e pelo editor nativo.','tools'],['Seu mundo pode rodar offline.','Single player é local. Multiplayer autoritativo é opcional. Mantenha criação, simulação e saves duráveis sob seu controle.','network']],read:'Explore o sistema',
  galleryTag:'CAPTURAS NATIVAS / VISTAS SELECIONADAS',galleryTitle:'Veja ganhar<br><em>forma.</em>',galleryBody:'Um olhar mais próximo sobre paisagens, vegetação e arquitetura criadas com a Ignis. Escolha uma vista ou amplie a captura.'
 }
};
export function renderStories(lang){
 const d=text[lang==='pt'?'pt':'en'],idx=lang==='pt'?1:0;
 const image=(id,cls='')=>{const m=nativeMedia[id];return `<button class="story-image capture-open ${cls}" data-capture="${id}" aria-label="${idx?'Ampliar captura':'Enlarge capture'}"><img src="${m.src}" width="${m.width}" height="${m.height}" alt="${m.caption[idx]}" loading="lazy" decoding="async"><span aria-hidden="true">↗</span></button>`;};
 const link=(label,group)=>`<a class="story-link" href="#capabilities" data-explore="${group}">${label}<span aria-hidden="true">↗</span></a>`;
 return `<article id="ignis-horizon" class="product-story horizon-story"><div class="story-heading"><span class="engine-kicker">${d.horizonTag}</span><h3>${d.horizonTitle}</h3><p>${d.horizonBody}</p><a class="story-link" href="#horizon-architecture">${d.horizonLink}<span aria-hidden="true">↗</span></a></div>${image('horizon')}<div class="horizon-numbers"><p><strong>${idx?'30.000':'30,000'}</strong><span>${d.trees}</span></p><p><strong>${idx?'60.006':'60,006'}</strong><span>${d.meshes}</span></p><p><strong>18 km</strong><span>${d.distance}</span></p></div><details class="story-method"><summary>${d.method}<span aria-hidden="true">+</span></summary><p>${d.methodBody}</p></details>${renderHorizonArchitecture(lang)}</article>
 <article id="plant-generation" class="product-story plant-story"><div class="story-heading"><span class="engine-kicker">${d.plantsTag}</span><h3>${d.plantsTitle}</h3><p>${d.plantsBody}</p><ul>${d.plantsList.map(x=>`<li>${x}</li>`).join('')}</ul>${link(d.plantsLink,'botany')}</div><div class="plant-visual">${image('botany')}<span class="plant-coordinate" aria-hidden="true">IGNIS / BOTANY<br>SEED → ORGANS → GEOMETRY</span></div><details class="story-method"><summary>${d.method}<span aria-hidden="true">+</span></summary><p>${d.plantsNote}</p></details></article>
 <article id="living-landscapes" class="product-story distance-story"><div class="story-heading"><span class="engine-kicker">${d.worldTag}</span><h3>${d.worldTitle}</h3><p>${d.worldBody}</p>${link(d.worldLink,'world')}</div>${image('sunset')}</article>
 <div class="product-promises"><span class="engine-kicker">${d.promisesTag}</span><div>${d.promises.map((p,i)=>`<article><span class="promise-index">0${i+1} /</span><h3>${p[0]}</h3><p>${p[1]}</p>${link(d.read,p[2])}</article>`).join('')}</div></div>`;
}
export const galleryCopy=lang=>text[lang==='pt'?'pt':'en'];
